use glam::DVec3 as V;use ingetrazo_core::{scene::{Scene,SelectionItem},math::Ray,groups::Group};use ingetrazo_tools::{base::{Tool,ToolContext},select::SelectTool};
fn main(){let mut rows=serde_json::Map::new();for kind in ["Face","Edge","Group"]{for selected in [false,true]{let mut scene=Scene::new();scene.mesh.add_vertex(V::ZERO);scene.mesh.add_vertex(V::X*2.);scene.mesh.add_vertex(V::Y*2.);let target=if kind=="Edge"{scene.mesh.add_edge(0,1);SelectionItem::Edge(0)}else{scene.mesh.add_face(vec![0,1,2],vec![]);if kind=="Group"{let mut group=Group::new("target");group.mesh=std::mem::take(&mut scene.mesh);scene.groups.push(group);SelectionItem::Group(0)}else{SelectionItem::Face(0)}};if selected{scene.select(target.clone());}let origin=if kind=="Edge"{V::new(0.5,0.,1.)}else{V::new(0.5,0.5,1.)};let mut tool=SelectTool::new();tool.on_click(&mut scene,&ToolContext::with_modifiers(V::ZERO,Ray::new(origin,-V::Z),true,true,false));rows.insert(format!("{kind}_{}",if selected{"selected"}else{"unselected"}),serde_json::json!({"selected":scene.selection.contains(&target),"count":scene.selection.len()}));}}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
